// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.tts/** * NOUS — Emotional Prosody Model (§7 Emotional Prosody Engine). * * NOUS conveys emotion through its voice by adjusting pitch, rate, pause * pattern, and word emphasis. The Brain picks an [Emotion] based on the * user's emotional state, conversation context, active persona, and * urgency; the [EmotionalTtsEngine] converts that emotion into TTS engine * parameters. * * ## The 9 emotions * * | Emotion     | Pitch | Rate  | Pauses  | Emphasis | * |-------------|-------|-------|---------|----------| * | NEUTRAL     | 1.00  | 1.00  | normal | none     | * | HAPPY       | 1.15  | 1.05  | short  | light    | * | SAD         | 0.85  | 0.90  | long   | none     | * | URGENT      | 1.00  | 1.30  | none   | strong   | * | CALM        | 0.95  | 0.85  | long   | light    | * | WITTY       | 1.05  | 1.10  | punch  | light    | * | ANGRY       | 0.90  | 1.20  | short  | strong   | * | THOUGHTFUL  | 1.00  | 0.80  | long   | none     | * | APOLOGETIC  | 0.90  | 0.90  | long   | none     | * * These multipliers are applied on top of the active [VoicePersona]'s base * pitch and rate. For example, JARVIS (pitch=0.9) speaking HAPPY (×1.15) * results in an effective pitch of 0.9 × 1.15 = 1.035 — slightly higher * than JARVIS's neutral, but still lower than FRIDAY's neutral (1.1). * * ## Selection * * The Brain selects the emotion in `BrainPostProcessor` (Module 2) based * on: *  - User emotion (parallel SER from §16 — if user is angry, NOUS may *    respond CALM to de-escalate, or APOLOGETIC if NOUS made a mistake). *  - Persona (ULTRON never sounds HAPPY; JARVIS leans WITTY). *  - Urgency (smoke alarm → URGENT regardless of persona). *  - Conversation context (user just shared sad news → SAD or CALM). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§7 Text-to-Speech — Emotional Prosody Engine</a> */enum class Emotion(    /** Pitch multiplier applied on top of persona base pitch. 1.0 = no change. */    val pitchMultiplier: Float,    /** Speech rate multiplier applied on top of persona base rate. 1.0 = no change. */    val rateMultiplier: Float,    /** Where and how long to insert pauses for natural speech. */    val pausePattern: PausePattern,    /** Which words to stress (louder / longer). */    val emphasis: Emphasis,) {    NEUTRAL    (1.00f, 1.00f, PausePattern.NORMAL,    Emphasis.NONE),    HAPPY      (1.15f, 1.05f, PausePattern.SHORT,     Emphasis.LIGHT),    SAD        (0.85f, 0.90f, PausePattern.LONG,      Emphasis.NONE),    URGENT     (1.00f, 1.30f, PausePattern.NONE,      Emphasis.STRONG),    CALM       (0.95f, 0.85f, PausePattern.LONG,      Emphasis.LIGHT),    WITTY      (1.05f, 1.10f, PausePattern.PUNCHLINE, Emphasis.LIGHT),    ANGRY      (0.90f, 1.20f, PausePattern.SHORT,     Emphasis.STRONG),    THOUGHTFUL (1.00f, 0.80f, PausePattern.LONG,      Emphasis.NONE),    APOLOGETIC (0.90f, 0.90f, PausePattern.LONG,      Emphasis.NONE);    init {        // Sanity bounds — catch typos in the enum table above.        require(pitchMultiplier in 0.5f..2.0f) {            "$name pitchMultiplier $pitchMultiplier out of bounds [0.5, 2.0]"        }        require(rateMultiplier in 0.5f..2.0f) {            "$name rateMultiplier $rateMultiplier out of bounds [0.5, 2.0]"        }    }}// ──────────────────────────────────────────────────────────────────────────/** * Pause insertion strategy. * * The [EmotionalTtsEngine] inserts SSML `<break>` tags (or comma cues for * engines that don't support SSML) according to this pattern. */enum class PausePattern {    /** No pauses inserted — speak as fast as possible. URGENT. */    NONE,    /** Short pauses only at sentence boundaries. HAPPY, ANGRY. */    SHORT,    /** Normal punctuation-driven pauses. NEUTRAL. */    NORMAL,    /** Long pauses at clause boundaries + between sentences. SAD, CALM, THOUGHTFUL, APOLOGETIC. */    LONG,    /** Long pause before the punchline / key word of the sentence. WITTY. */    PUNCHLINE,}// ──────────────────────────────────────────────────────────────────────────/** * Word emphasis strategy. * * Implemented by the TTS engine via SSML `<emphasis>` (when supported) or * by wrapping important words in caps / asterisks for engines that don't. */enum class Emphasis {    /** No emphasis applied. */    NONE,    /** Light emphasis on the last content word of each sentence. */    LIGHT,    /** Strong emphasis on nouns and verbs. */    STRONG,}